Script.Workflow:
module Win8ButtonColors;
using presentation::*;
using presentation::controls::*;
namespace win8skin
{
  struct ButtonColors
  {
    Border : Color;
    G1 : Color;
    G2 : Color;
    Text : Color;
    Bullet : Color;
  }

  class ButtonColorState
  {
    prop Border : Color = {} {}
    prop G1 : Color = {} {}
    prop G2 : Color = {} {}
    prop Text : Color = {} {}
    prop Bullet : Color = {} {}

    new() {}

    new(colors : ButtonColors)
    {
      Border = colors.Border;
      G1 = colors.G1;
      G2 = colors.G2;
      Text = colors.Text;
      Bullet = colors.Bullet;
    }
  }

  func CompleteColorAnimation(animation : IGuiAnimation^, completed : func():void) : IGuiAnimation^
  ${
    $PlayAndWait animation;
    completed();
  }

  func GetButtonColors(enabled : bool, state : ButtonState) : ButtonColors
  {
    return not enabled ? win8Colors.ButtonDisabled :
      state == ButtonState::Pressed ? win8Colors.ButtonPressed :
      state == ButtonState::Active ? win8Colors.ButtonHovered : win8Colors.ButtonNormal;
  }

  func GetCheckedColors(enabled : bool, state : ButtonState, selected : bool) : ButtonColors
  {
    var colors = not enabled ? win8Colors.CheckedDisabled :
      state == ButtonState::Pressed ? win8Colors.CheckedPressed :
      state == ButtonState::Active ? win8Colors.CheckedHovered : win8Colors.CheckedNormal;
    return {
      Border: colors.Border;
      G1: colors.G1;
      G2: colors.G2;
      Text: colors.Text;
      Bullet: selected ? colors.Bullet : {r:colors.Bullet.r; g:colors.Bullet.g; b:colors.Bullet.b; a:win8Colors.Transparent.a;};
    };
  }

  func GetScrollButtonColors(enabled : bool, state : ButtonState, arrow : bool) : ButtonColors
  {
    if (arrow)
    {
      return not enabled ? win8Colors.ScrollArrowDisabled :
        state == ButtonState::Pressed ? win8Colors.ScrollArrowPressed :
        state == ButtonState::Active ? win8Colors.ScrollArrowActive : win8Colors.ScrollArrowNormal;
    }
    return not enabled ? win8Colors.ScrollHandleDisabled :
      state == ButtonState::Pressed ? win8Colors.ScrollHandlePressed :
      state == ButtonState::Active ? win8Colors.ScrollHandleActive : win8Colors.ScrollHandleNormal;
  }
}

Instance.ref.Members:
var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(win8Colors.ButtonNormal));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetButtonColors(self.VisuallyEnabled, self.State)), cast UInt64 120), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}

var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(GetCheckedColors(true, ButtonState::Normal, false)));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetCheckedColors(self.VisuallyEnabled, self.State, self.Selected)), cast UInt64 120), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}

var animationBuilder : ButtonColorAnimation^ = new ButtonColorAnimation^(new ButtonColorState^(GetCheckedColors(true, ButtonState::Normal, false)));
var lastAnimation : IGuiAnimation^ = null;

func UpdateColors() : void
{
  KillAnimation(lastAnimation);
  lastAnimation = CompleteColorAnimation(animationBuilder.CreateAnimation(new ButtonColorState^(GetCheckedColors(self.VisuallyEnabled, self.State, self.Selected)), cast UInt64 120), func():void { animationBuilder.Interpolate(1.0); });
  AddAnimation(lastAnimation);
}
